from pico_ioc import component
from pico_resilience import retryable

class QuoteUnavailable(Exception):
    pass

@component
class FlakyFeed:
    """An upstream price feed that is not always there when you call it."""

    def __init__(self):
        self.calls = 0

    def spot_price(self) -> float:
        self.calls += 1
        if self.calls % 3 != 0:
            raise QuoteUnavailable("feed hiccup")
        return 101.25

@component
class QuoteService:
    def __init__(self, feed: FlakyFeed):
        self._feed = feed

    # TODO: callers of quote() should never see the feed's hiccups.
    # Fix it here, without touching FlakyFeed.
    def quote(self) -> dict:
        return {"spot": self._feed.spot_price()}

