from pico_ioc import component
from pico_resilience import circuit_breaker

class FeedDown(Exception):
    pass

@component
class DeadFeed:
    def __init__(self):
        self.calls = 0

    def spot_price(self) -> float:
        self.calls += 1
        raise FeedDown("connection refused")

@component
class QuoteService:
    def __init__(self, feed: DeadFeed):
        self._feed = feed

    @circuit_breaker(failure_threshold=3, reset_timeout_seconds=60)
    def quote(self) -> dict:
        return {"spot": self._feed.spot_price()}

